96	        if (*targetNode != *message->getRemoteNode()) {
97	          // Node ID has changed. Drop previous node ID from
98	          // DHTRoutingTable
99	          A2_LOG_DEBUG(
100	              fmt("Node ID has changed: old:%s, new:%s",
101	                  util::toHex(targetNode->getID(), DHT_ID_LENGTH).c_str(),
102	                  util::toHex(message->getRemoteNode()->getID(), DHT_ID_LENGTH)
103	                      .c_str()));
104	          routingTable_->dropNode(targetNode);
105	        }
106	        return std::make_pair(std::move(message), entry->popCallback());
107	      }
108	      catch (RecoverableException& e) {
109	        handleTimeoutEntry(entry.get());
110	        throw;
111	      }
112	    }
113	  }
114	  A2_LOG_DEBUG("Tracker entry not found.");
115	  return std::pair<std::unique_ptr<DHTResponseMessage>,
116	                   std::unique_ptr<DHTMessageCallback>>{};
117	}
118	
119	void DHTMessageTracker::handleTimeoutEntry(DHTMessageTrackerEntry* entry)
120	{
121	  try {
122	    auto& node = entry->getTargetNode();
123	    A2_LOG_DEBUG(fmt("Message timeout: To:%s:%u", node->getIPAddress().c_str(),
124	                     node->getPort()));
125	    node->updateRTT(std::chrono::duration_cast<std::chrono::milliseconds>(
126	        entry->getElapsed()));
127	    node->timeout();
128	    if (node->isBad()) {
129	      A2_LOG_DEBUG(fmt("Marked bad: %s:%u", node->getIPAddress().c_str(),
130	                       node->getPort()));
131	      routingTable_->dropNode(node);
132	    }
133	    auto& callback = entry->getCallback();
134	    if (callback) {
135	      callback->onTimeout(node);
136	    }
137	  }
138	  catch (RecoverableException& e) {
139	    A2_LOG_INFO_EX("Exception thrown while handling timeouts.", e);
140	  }
141	}
142	
143	void DHTMessageTracker::handleTimeout()
144	{
145	  entries_.erase(
146	      std::remove_if(std::begin(entries_), std::end(entries_),
147	                     [&](const std::unique_ptr<DHTMessageTrackerEntry>& ent) {
148	                       if (ent->isTimeout()) {
149	                         handleTimeoutEntry(ent.get());
150	                         return true;
151	                       }
152	                       else {
153	                         return false;
154	                       }
155	                     }),
156	      std::end(entries_));
157	}
158	
159	const DHTMessageTrackerEntry*
160	DHTMessageTracker::getEntryFor(const DHTMessage* message) const
161	{
162	  for (auto& ent : entries_) {
163	    if (ent->match(message->getTransactionID(),
164	                   message->getRemoteNode()->getIPAddress(),
165	                   message->getRemoteNode()->getPort())) {
166	      return ent.get();
167	    }
168	  }
169	  return nullptr;
170	}
171	
172	size_t DHTMessageTracker::countEntry() const { return entries_.size(); }
173	
174	void DHTMessageTracker::setRoutingTable(DHTRoutingTable* routingTable)
175	{
176	  routingTable_ = routingTable;
177	}
178	
179	void DHTMessageTracker::setMessageFactory(DHTMessageFactory* factory)
180	{
181	  factory_ = factory;
182	}
183	
184	} // namespace aria2
