51	    const std::shared_ptr<DHTMessageTracker>& tracker)
52	    : tracker_{tracker}, timeout_{DHT_MESSAGE_TIMEOUT}
53	{
54	}
55	
56	void DHTMessageDispatcherImpl::addMessageToQueue(
57	    std::unique_ptr<DHTMessage> message, std::chrono::seconds timeout,
58	    std::unique_ptr<DHTMessageCallback> callback)
59	{
60	  messageQueue_.push_back(make_unique<DHTMessageEntry>(
61	      std::move(message), std::move(timeout), std::move(callback)));
62	}
63	
64	void DHTMessageDispatcherImpl::addMessageToQueue(
65	    std::unique_ptr<DHTMessage> message,
66	    std::unique_ptr<DHTMessageCallback> callback)
67	{
68	  addMessageToQueue(std::move(message), timeout_, std::move(callback));
69	}
70	
71	bool DHTMessageDispatcherImpl::sendMessage(DHTMessageEntry* entry)
72	{
73	  try {
74	    if (entry->message->send()) {
75	      if (!entry->message->isReply()) {
76	        tracker_->addMessage(entry->message.get(), entry->timeout,
77	                             std::move(entry->callback));
78	      }
79	      A2_LOG_INFO(fmt("Message sent: %s", entry->message->toString().c_str()));
80	    }
81	    else {
82	      return false;
83	    }
84	  }
85	  catch (RecoverableException& e) {
86	    A2_LOG_INFO_EX(
87	        fmt("Failed to send message: %s", entry->message->toString().c_str()),
88	        e);
89	    // Add message to DHTMessageTracker with timeout 0 to treat it as
90	    // time out. Without this, we have untracked message and some of
91	    // DHTTask(such as DHTAbstractNodeLookupTask) don't finish
92	    // forever.
93	    if (!entry->message->isReply()) {
94	      tracker_->addMessage(entry->message.get(), 0_s,
95	                           std::move(entry->callback));
96	    }
97	  }
98	  return true;
99	}
100	
101	void DHTMessageDispatcherImpl::sendMessages()
102	{
103	  auto itr = std::begin(messageQueue_);
104	  for (; itr != std::end(messageQueue_); ++itr) {
105	    if (!sendMessage((*itr).get())) {
106	      break;
107	    }
108	  }
109	  messageQueue_.erase(std::begin(messageQueue_), itr);
110	  A2_LOG_DEBUG(fmt("%lu dht messages remaining in the queue.",
111	                   static_cast<unsigned long>(messageQueue_.size())));
112	}
113	
114	size_t DHTMessageDispatcherImpl::countMessageInQueue() const
115	{
116	  return messageQueue_.size();
117	}
