95	bool DHTInteractionCommand::execute()
96	{
97	  // We need to keep this command alive while TrackerWatcherCommand
98	  // needs this.
99	  if (e_->getRequestGroupMan()->downloadFinished() ||
100	      (e_->isHaltRequested() && udpTrackerClient_->getNumWatchers() == 0)) {
101	    A2_LOG_DEBUG("DHTInteractionCommand exiting");
102	    return true;
103	  }
104	  else if (e_->isForceHaltRequested()) {
105	    udpTrackerClient_->failAll();
106	    A2_LOG_DEBUG("DHTInteractionCommand exiting");
107	    return true;
108	  }
109	
110	  taskQueue_->executeTask();
111	
112	  std::string remoteAddr;
113	  uint16_t remotePort;
114	  std::array<unsigned char, 64_k> data;
115	  try {
116	    while (1) {
117	      ssize_t length = connection_->receiveMessage(data.data(), data.size(),
118	                                                   remoteAddr, remotePort);
119	      if (length <= 0) {
120	        break;
121	      }
122	      if (data[0] == 'd') {
123	        // udp tracker response does not start with 'd', so assume
124	        // this message belongs to DHT. nothrow.
125	        receiver_->receiveMessage(remoteAddr, remotePort, data.data(), length);
126	      }
127	      else {
128	        // this may be udp tracker response. nothrow.
129	        std::shared_ptr<UDPTrackerRequest> req;
130	        if (udpTrackerClient_->receiveReply(req, data.data(), length,
131	                                            remoteAddr, remotePort,
132	                                            global::wallclock()) == 0) {
133	          if (req->action == UDPT_ACT_ANNOUNCE) {
134	            auto c = static_cast<TrackerWatcherCommand*>(req->user_data);
135	            if (c) {
136	              c->setStatus(Command::STATUS_ONESHOT_REALTIME);
137	              e_->setNoWait(true);
138	            }
139	          }
140	        }
141	      }
142	    }
143	  }
144	  catch (RecoverableException& e) {
145	    A2_LOG_INFO_EX("Exception thrown while receiving UDP message.", e);
146	  }
147	  receiver_->handleTimeout();
148	  udpTrackerClient_->handleTimeout(global::wallclock());
149	  dispatcher_->sendMessages();
150	  while (!udpTrackerClient_->getPendingRequests().empty()) {
151	    // no throw
152	    ssize_t length = udpTrackerClient_->createRequest(
153	        data.data(), data.size(), remoteAddr, remotePort, global::wallclock());
154	    if (length == -1) {
155	      break;
156	    }
157	    try {
158	      // throw
159	      connection_->sendMessage(data.data(), length, remoteAddr, remotePort);
160	      udpTrackerClient_->requestSent(global::wallclock());
161	    }
162	    catch (RecoverableException& e) {
163	      A2_LOG_INFO_EX("Exception thrown while sending UDP tracker request.", e);
164	      udpTrackerClient_->requestFail(UDPT_ERR_NETWORK);
165	    }
166	  }
167	  e_->addRoutineCommand(std::unique_ptr<Command>(this));
168	  return false;
169	}
