96	void DHTPeerLookupTask::onFinish()
97	{
98	  A2_LOG_DEBUG(fmt("Peer lookup for %s finished",
99	                   util::toHex(getTargetID(), DHT_ID_LENGTH).c_str()));
100	  // send announce_peer message to K closest nodes
101	  size_t num = DHTBucket::K;
102	  for (auto i = std::begin(getEntries()), eoi = std::end(getEntries());
103	       i != eoi && num > 0; ++i) {
104	    if (!(*i)->used) {
105	      continue;
106	    }
107	    auto& node = (*i)->node;
108	    std::string idHex = util::toHex(node->getID(), DHT_ID_LENGTH);
109	    std::string token = tokenStorage_[idHex];
110	    if (token.empty()) {
111	      A2_LOG_DEBUG(fmt("Token is empty for ID:%s", idHex.c_str()));
112	      continue;
113	    }
114	    getMessageDispatcher()->addMessageToQueue(
115	        getMessageFactory()->createAnnouncePeerMessage(
116	            node,
117	            getTargetID(), // this is infoHash
118	            tcpPort_, token));
119	    --num;
120	  }
121	}
